  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Pirfenidone, a structurally related 1-phenyl pyridone, is rapidly absorbed with high oral bioavailability in humans and nonclinical species, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Edaravone, the closest pyrazolone analogue, has an absolute oral bioavailability of 57% in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Clobazam, an N-phenyl heterocycle, has 90–100% oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Sulphinpyrazone, another N-phenyl heterocycle, has 90% absolute oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Mephobarbital, a related N-methyl/N-phenyl heterocycle, has 71% absolute oral bioavailability in humans, above the threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is antipyrine (phenazone), a small neutral pyrazolone. All transferable experimental evidence points to high oral bioavailability: the closest analogue edaravone has F=57%, pirfenidone is highly bioavailable, and several N-phenyl heterocycles show 71–100% F. Physicochemical properties are favorable, so F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for antipyrine itself is included in the provided records.",
    "The closest analogue edaravone differs by an NH instead of an N-methyl group, though its quantitative F is still high.",
    "Some records are qualitative or use different formulations, but quantitative absolute bioavailability values consistently exceed 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

